// Plan 292: im.gamer brand helpers. Colours live in ./brand-palette.ts.
import {
  BRAND_NAME,
  BRAND_PALETTES,
  BRAND_PALETTE_KEY,
  type BrandPalette,
} from "./brand-palette";

export { BRAND_NAME };

export const BRAND: BrandPalette = BRAND_PALETTES[BRAND_PALETTE_KEY];

/** Static icons generated by scripts/brand-icons.mjs for the active palette. */
export const BRAND_ICON_DIR = `/brand/${BRAND_PALETTE_KEY}`;
export const BRAND_FAVICON = `${BRAND_ICON_DIR}/favicon.ico`;

/** True when the site name is the brand itself (shown as the wordmark). */
export const isBrandName = (name: string | null | undefined) =>
  (name || "").trim().toLowerCase() === BRAND_NAME;

/**
 * Publishes the palette as CSS variables (--brand-from / -to / -accent /
 * -soft / -ring) on <html>. Called once at start-up, before the first render.
 */
export const applyBrandVars = () => {
  if (typeof document === "undefined") {
    return;
  }
  const style = document.documentElement.style;

  style.setProperty("--brand-from", BRAND.from);
  style.setProperty("--brand-to", BRAND.split ? BRAND.from : BRAND.to);
  style.setProperty("--brand-to-raw", BRAND.to);
  style.setProperty("--brand-accent", BRAND.accent);
  style.setProperty("--brand-soft", BRAND.soft);
  style.setProperty("--brand-ring", BRAND.ring);
};
